SELECT male_post_op_icu_patients_95th_percentile.instability_score, COUNT(*) filter (WHERE fever > 38.5) AS fever_episodes, COUNT(*) filter (WHERE oxygen_saturation < 90) AS low_oxygen_episodes, COUNT(*) filter (WHERE respiratory_rate > 20) AS high_respiratory_rate_episodes, SUM(duration) AS total_duration FROM male_post_op_icu_patients JOIN male_post_op_icu_patients_95th_percentile ON male_post_op_icu_patients.instability_score <= male_post_op_icu_patients_95th_percentile.instability_score GROUP BY male_post_op_icu_patients_95th_percentile.instability_score;